#include <iostream>

// Recursive function to calculate Fibonacci sequence
int fibonacciRecursive(int n) {
    if (n <= 1) {
        return n;
    }
    return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

// Iterative function to calculate Fibonacci sequence
int fibonacciIterative(int n) {
    if (n <= 1) {
        return n;
    }
    int a = 0, b = 1, fib = 0;
    for (int i = 2; i <= n; ++i) {
        fib = a + b;
        a = b;
        b = fib;
    }
    return fib;
}

int main() {
    int n;
    std::cout << "Enter a number: ";
    std::cin >> n;

    std::cout << "Fibonacci (Recursive) of " << n << " is " << fibonacciRecursive(n) << std::endl;
    std::cout << "Fibonacci (Iterative) of " << n << " is " << fibonacciIterative(n) << std::endl;

    return 0;
}
```

