Certainly! Here's both the recursive and iterative implementations of Fibonacci sequence in C++:

```cpp
#include <iostream>
using namespace std;

// Recursive method to calculate Fibonacci number
int fibonacciRecursive(int n) {
    if (n <= 1)
        return n;
    return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

// Iterative method to calculate Fibonacci number
int fibonacciIterative(int n) {
    if (n <= 1)
        return n;
    int prev = 0, curr = 1;
    for (int i = 2; i <= n; ++i) {
        int next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

int main() {
    int n;
    cout << "Enter the position of Fibonacci sequence: ";
    cin >> n;

    cout << "Fibonacci number (recursive) at position " << n << ": " 
         << fibonacciRecursive(n) << endl;

    cout << "Fibonacci number (iterative) at position " << n << ": " 
         << fibonacciIterative(n) << endl;

    return 0;
}
```

### How it works:
- The `fibonacciRecursive` function calculates the Fibonacci number using simple recursion by dividing the problem until the base cases (`n <= 1`) are reached.
- The `fibonacciIterative` uses a loop to iteratively calculate each Fibonacci number up to position `n`, which is more efficient for large `n`.

