2. Use a custom property drawer or attribute to conditionally expose certain variables depending on the card type.

A simple approach without custom drawers is to **use [ConditionalHide]** attributes from third-party libraries, but since Unity doesn't have this built-in, you'd typically implement a custom property drawer for this purpose.

3. Example of implementing a property drawer that shows/hides fields:

Create an attribute:

```csharp
public class ShowIfAttribute : PropertyAttribute
{
    public string conditionField;
    public object compareValue;

    public ShowIfAttribute(string conditionField, object compareValue)
    {
        this.conditionField = conditionField;
        this.compareValue = compareValue;
    }
}
```

Implement a corresponding property drawer:

```csharp
#if UNITY_EDITOR
using UnityEditor;
using UnityEngine;

[CustomPropertyDrawer(typeof(ShowIfAttribute))]
public class ShowIfDrawer : PropertyDrawer
{
    public override float GetPropertyHeight(SerializedProperty property, GUIContent label)
    {
        ShowIfAttribute showIf = (ShowIfAttribute)attribute;
        SerializedProperty conditionProperty = property.serializedObject.FindProperty(showIf.conditionField);

        bool conditionMet = false;

        if (conditionProperty != null)
        {
            if (conditionProperty.propertyType == SerializedPropertyType.Enum)
            {
                int index = conditionProperty.enumValueIndex;
                conditionMet = index.ToString() == showIf.compareValue.ToString();
            }
        }

        return conditionMet ? EditorGUI.GetPropertyHeight(property, label, true) : 0f;
    }

    public override void OnGUI(Rect position, SerializedProperty property, GUIContent label)
    {
        ShowIfAttribute showIf = (ShowIfAttribute)attribute;
        SerializedProperty conditionProperty = property.serializedObject.FindProperty(showIf.conditionField);

        if (conditionProperty != null)
        {
            bool conditionMet = false;

            if (conditionProperty.propertyType == SerializedPropertyType.Enum)
            {
                int index = conditionProperty.enumValueIndex;
                conditionMet = index.ToString() == showIf.compareValue.ToString();
            }

            if (conditionMet)
            {
                EditorGUI.PropertyField(position, property, label, true);
            }
        }
    }
}
#endif
```

