```csharp
using System;

class TriangleAreaCalculator
{
    public static void Main(string[] args)
    {
        // Example side lengths
        double sideA = 3;
        double sideB = 4;
        double sideC = 5;

        try
        {
            double area = CalculateTriangleArea(sideA, sideB, sideC);
            Console.WriteLine($"The area of the triangle is: {area}");
        }
        catch (ArgumentException ex)
        {
            Console.WriteLine(ex.Message);
        }
    }

    public static double CalculateTriangleArea(double a, double b, double c)
    {
        if (!IsValidTriangle(a, b, c))
        {
            throw new ArgumentException("The provided side lengths do not form a valid triangle.");
        }

        double semiPerimeter = (a + b + c) / 2;
        double area = Math.Sqrt(semiPerimeter * (semiPerimeter - a) * (semiPerimeter - b) * (semiPerimeter - c));

        return area;
    }

    public static bool IsValidTriangle(double a, double b, double c)
    {
        // Check if all sides are positive and satisfy the triangle inequality theorem
        return a > 0 && b > 0 && c > 0 &&
               a + b > c &&
               a + c > b &&
               b + c > a;
    }
}
```

