  uint32_t timer_clock = VARIANT_MCK / 128; // e.g., 84MHz / 128 ≈ 656,250 Hz
  uint32_t rc = timer_clock / freq; // RC value

  // Set the RC compare value
  tc->TC_CHANNEL[channel].TC_RC = rc;

  // Enable the timer
  tc->TC_CHANNEL[channel].TC_CCR = TC_CCR_CLKEN | TC_CCR_SWTRG;

