               TC_CMR_TCCLKS_TIMER_CLOCK4 | // clock source
               TC_CMR_WAVE |               // waveform mode
               TC_CMR_WAVSEL_UP_RC);       // counter resets on RC compare

  // Set the RC compare value
  tc->TC_CHANNEL[TC_CHANNEL].TC_RC = rc;

  // Enable the timer
