         public decimal Price { get; set; }
         public int Stock { get; set; }
     }
     ```

3. **Configure DbContext**:
   - Create `SalesItemsContext.cs`:
     ```csharp
     public class SalesItemsContext : DbContext
     {
         public SalesItemsContext(DbContextOptions<SalesItemsContext> options) : base(options) { }

         public DbSet<Sale> Sales { get; set; }
         public DbSet<Item> Items { get; set; }
     }
     ```

   - Update `Program.cs` to register the context:
     ```csharp
     builder.Services.AddDbContext<SalesItemsContext>(options =>
         options.UseSqlServer(builder.Configuration.GetConnectionString("DefaultConnection")));
     ```

4. **Create Controllers**:
   - `SalesController.cs`:
     ```csharp
     [ApiController]
     [Route("api/[controller]")]
     public class SalesController : ControllerBase
     {
         private readonly SalesItemsContext _context;

         public SalesController(SalesItemsContext context)
         {
             _context = context;
         }

         [HttpGet]
         public async Task<ActionResult<IEnumerable<Sale>>> GetSales()
         {
             return await _context.Sales.ToListAsync();
         }

         [HttpGet("{id}")]
         public async Task<ActionResult<Sale>> GetSale(int id)
         {
             var sale = await _context.Sales.FindAsync(id);
             if (sale == null)
             {
                 return NotFound();
             }

             return sale;
         }

         [HttpPost]
         public async Task<ActionResult<Sale>> CreateSale(Sale sale)
         {
             _context.Sales.Add(sale);
             await _context.SaveChangesAsync();

             return CreatedAtAction(nameof(GetSale), new { id = sale.Id }, sale);
         }

         [HttpPut("{id}")]
         public async Task<IActionResult> UpdateSale(int id, Sale sale)
         {
             if (id != sale.Id)
             {
                 return BadRequest();
             }

             _context.Entry(sale).State = EntityState.Modified;

             try
             {
                 await _context.SaveChangesAsync();
             }
             catch (DbUpdateConcurrencyException)
             {
                 if (!SaleExists(id))
                 {
                     return NotFound();
                 }
                 else
                 {
                     throw;
                 }
             }

             return NoContent();
         }

         [HttpDelete("{id}")]
         public async Task<IActionResult> DeleteSale(int id)
         {
             var sale = await _context.Sales.FindAsync(id);
             if (sale == null)
             {
                 return NotFound();
             }

             _context.Sales.Remove(sale);
             await _context.SaveChangesAsync();

             return NoContent();
         }

         private bool SaleExists(int id) => _context.Sales.Any(e => e.Id == id);
     }
     ```

