```csharp
using Microsoft.AspNetCore.Mvc;
using System.Collections.Generic;
using System.Linq;

[ApiController]
[Route("api/[controller]")]
public class ItemsController : ControllerBase
{
    // GET all items
    [HttpGet]
    public ActionResult<IEnumerable<Item>> Get()
    {
        return Ok(DataStore.Items);
    }

    // GET item by id
    [HttpGet("{id}")]
    public ActionResult<Item> Get(int id)
    {
        var item = DataStore.Items.FirstOrDefault(i => i.Id == id);
        if (item == null)
            return NotFound();
        return Ok(item);
    }

    // POST create new item
    [HttpPost]
    public ActionResult<Item> Post([FromBody] Item newItem)
    {
        newItem.Id = DataStore.Items.Count > 0 ? DataStore.Items.Max(i => i.Id) + 1 : 1;
        DataStore.Items.Add(newItem);
        return CreatedAtAction(nameof(Get), new { id = newItem.Id }, newItem);
    }

    // PUT update item
    [HttpPut("{id}")]
    public ActionResult Put(int id, [FromBody] Item updatedItem)
    {
        var existingItem = DataStore.Items.FirstOrDefault(i => i.Id == id);
        if (existingItem == null)
            return NotFound();

        existingItem.Name = updatedItem.Name;
        existingItem.Price = updatedItem.Price;
        existingItem.Quantity = updatedItem.Quantity;
        return NoContent();
    }

    // DELETE item
    [HttpDelete("{id}")]
    public ActionResult Delete(int id)
    {
        var item = DataStore.Items.FirstOrDefault(i => i.Id == id);
        if (item == null)
            return NotFound();

        DataStore.Items.Remove(item);
        return NoContent();
    }
}
