### Step 5: Create Controller for Sales

**Controllers/SalesController.cs**
```csharp
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;
using System.Linq;

[ApiController]
[Route("api/[controller]")]
public class SalesController : ControllerBase
{
    // GET all sales
    [HttpGet]
    public ActionResult<IEnumerable<Sale>> Get()
    {
        return Ok(DataStore.Sales);
    }

    // GET sale by id
    [HttpGet("{id}")]
    public ActionResult<Sale> Get(int id)
    {
        var sale = DataStore.Sales.FirstOrDefault(s => s.Id == id);
        if (sale == null)
            return NotFound();
        return Ok(sale);
    }

    // POST create new sale
    [HttpPost]
    public ActionResult<Sale> Post([FromBody] Sale newSale)
    {
        newSale.Id = DataStore.Sales.Count > 0 ? DataStore.Sales.Max(s => s.Id) + 1 : 1;
        // Calculate total amount based on items
        newSale.TotalAmount = newSale.Items.Sum(i => i.TotalPrice);
        DataStore.Sales.Add(newSale);
        return CreatedAtAction(nameof(Get), new { id = newSale.Id }, newSale);
    }

    // PUT update sale
    [HttpPut("{id}")]
    public ActionResult Put(int id, [FromBody] Sale updatedSale)
    {
        var existingSale = DataStore.Sales.FirstOrDefault(s => s.Id == id);
        if (existingSale == null)
            return NotFound();

        existingSale.Date = updatedSale.Date;
        existingSale.Items = updatedSale.Items;
        existingSale.TotalAmount = existingSale.Items.Sum(i => i.TotalPrice);
        return NoContent();
    }

    // DELETE sale
    [HttpDelete("{id}")]
    public ActionResult Delete(int id)
    {
        var sale = DataStore.Sales.FirstOrDefault(s => s.Id == id);
        if (sale == null)
            return NotFound();

        DataStore.Sales.Remove(sale);
        return NoContent();
    }
}
